/*
  Theory metadata extracted from the classic 120-theory quiz (src/app.js).
  Used by the theory explorer for theories that do not yet have claims.
  Fields: id, name, category, summary, signature, detail.
*/
window.THEORIES_120_VERSION = '1';

window.THEORIES_120 = Object.freeze([{"id":1,"name":"Analytic idealism","category":"Idealism","summary":"Only cosmic consciousness fundamentally exists; the physical world is what universal consciousness's thoughts and feelings look like from the outside.","signature":"We are \"dissociated alters\" of one cosmic mind, like whirlpools in a stream.","detail":"Brains don't cause experience — a brain is the image of inner experience seen from the outside."},{"id":2,"name":"Advaita Vedānta nondualism","category":"Idealism","summary":"Pure, self-luminous consciousness (Brahman) is the sole reality; individual selves and the world are appearances produced by ignorance.","signature":"Consciousness is self-shining (svaprakāśa): it needs no second thing to reveal it and is never an object.","detail":"Feelings, thoughts, and perceptions belong to an insentient \"inner organ\" (mind), not to consciousness itself."},{"id":3,"name":"Conscious realism","category":"Idealism","summary":"Reality is a vast network of interacting conscious agents; space, time, and physical objects are just the \"user interface\" evolution built for us.","signature":"Perception evolved for fitness, not truth — like desktop icons hiding the computer's real workings.","detail":"Consciousness creates brains and spacetime, not the reverse."},{"id":4,"name":"Substance dualism","category":"Dualism","summary":"Mind is a fundamentally different kind of thing from the physical body — not made of matter at all — and can in principle exist without it.","signature":"The classic \"soul\" view: a thinking thing vs. an extended thing.","detail":"Allows the self to survive bodily death."},{"id":5,"name":"Naturalistic / property dualism","category":"Dualism","summary":"Consciousness is a fundamental, irreducible feature of nature — like mass or charge — governed by undiscovered psychophysical laws, but nothing supernatural.","signature":"Accepts the causal closure of physics; no soul pushing neurons around.","detail":"Motivated by the \"hard problem\" and the conceivability of philosophical zombies."},{"id":6,"name":"Interactionist dualism","category":"Dualism","summary":"A nonphysical self-conscious mind genuinely interacts with the brain — selecting, interpreting, unifying neural activity — so physics is not causally closed.","signature":"Mind-to-brain causation is real (Eccles's \"liaison brain\").","detail":"Consciousness must affect behavior, or evolution could never have selected for it."},{"id":7,"name":"Emergent dualism","category":"Dualism","summary":"Sufficiently organized brains naturally generate a genuinely new, nonphysical conscious self (a \"soul\") via as-yet-unknown psychophysical laws.","signature":"Combines strong brain dependence with real substance dualism.","detail":"The emergent self is an individual subject, not just a property — unity of consciousness demands it."},{"id":8,"name":"Spinozan dual-aspect monism","category":"Neutral monism","summary":"There is one substance (God-or-Nature); mind and body are the same thing expressed two ways — under the attributes of thought and extension.","signature":"Mind and body never interact; they are one item under two descriptions.","detail":"Dissolves the interaction problem, at the price of making mentality as pervasive as physicality."},{"id":9,"name":"Jamesian neutral monism","category":"Neutral monism","summary":"Mind and matter are both built from a more primitive \"pure experience\" that is itself neither mental nor physical.","signature":"The same neutral \"stuff\" counts as mental or physical depending on how it's organized.","detail":"Consciousness isn't a substance but a function/arrangement of experience."},{"id":10,"name":"Russellian monism","category":"Neutral monism","summary":"Physics describes only the structure and relations of matter; its hidden intrinsic nature — what matter is in itself, beneath the equations (philosophers call these its \"quiddities\") — is where consciousness fits in.","signature":"Science tells us what matter does, never what it is intrinsically.","detail":"Variants: the intrinsic nature is felt experience, a precursor of experience, or strictly neutral (treated here as the neutral variant; the panpsychist variants live under Panpsychism below)."},{"id":11,"name":"Micropsychism","category":"Panpsychism","summary":"The smallest constituents of matter already possess rudimentary felt experience.","signature":"Consciousness is fundamental and ubiquitous, not an emergence miracle.","detail":"Faces the combination problem: how do micro-experiences combine into one unified human experience?"},{"id":12,"name":"Cosmopsychism","category":"Panpsychism","summary":"The universe as a whole is conscious first; individual minds are fragments or dissociated parts of cosmic consciousness.","signature":"Inverts the combination problem into a \"decombination\" problem: how does one cosmic mind split into many?","detail":"The fundamental subject is the cosmos, not particles (Goff's recent \"hybrid\" view lands here)."},{"id":13,"name":"Panprotopsychism / panqualityism","category":"Panpsychism","summary":"The basic building blocks have proto-conscious qualities — qualitative but not yet experienced — and full consciousness arises only when they're organized into a subject.","signature":"Avoids attributing actual subjects (\"micro-selves\") to electrons.","detail":"Coleman: fundamental qualities become conscious when \"made subjectively available,\" e.g., by higher-order awareness."},{"id":14,"name":"Mind–brain identity theory","category":"Materialism — biological & identity","summary":"Conscious states literally are brain states — pain is C-fiber firing — just described in two different vocabularies.","signature":"No extra properties or substances; maximum parsimony.","detail":"The \"explanatory gap\" is a cognitive illusion, not evidence against identity."},{"id":15,"name":"Biological naturalism","category":"Materialism — biological & identity","summary":"Consciousness is a real, irreducible-but-natural biological feature of brains: caused by neurons, realized as a higher-level feature, like digestion is of the gut.","signature":"Causally reducible to brain processes but not ontologically reducible (first-person vs. third-person ontology).","detail":"Consciousness is causally efficacious, not an epiphenomenon."},{"id":16,"name":"Non-reductive physicalism / strong emergence","category":"Materialism — biological & identity","summary":"Consciousness is wholly physical but genuinely new: an emergent level of brain organization with real causal powers, irreducible to neurons.","signature":"Real top-down causation: the mind moves molecules.","detail":"Emergence is lawful but irreducible — more than the sum of its parts."},{"id":17,"name":"Functionalism / computationalism","category":"Materialism — functional & computational","summary":"What makes a state conscious is its causal role — inputs, internal transitions, outputs — not what it's made of, so minds are multiply realizable.","signature":"\"We could be made of Swiss cheese and it wouldn't matter.\"","detail":"Brain as hardware, mind as software."},{"id":18,"name":"Global Workspace Theory","category":"Materialism — functional & computational","summary":"A mental state is conscious when it wins a competition and gets \"broadcast\" brain-wide to many specialized processors at once.","signature":"Consciousness = global accessibility of information (the \"theater\" metaphor).","detail":"Grounded in specific neurobiology: prefrontal-parietal \"workspace neurons\" and \"ignition.\""},{"id":19,"name":"Integrated Information Theory (IIT)","category":"Materialism — functional & computational","summary":"Consciousness is integrated information: an experience is as conscious as its parts are woven into one irreducible whole — researchers measure this with a quantity they call phi.","signature":"Starts from basic facts about experience and works out, mathematically, what a physical system must be like to have them.","detail":"Consciousness is a structure, not a function or computation — a simulation doesn't count."},{"id":20,"name":"Higher-order thought theory","category":"Materialism — functional & computational","summary":"A mental state is conscious only when you have a (possibly unconscious) higher-order thought about being in that state.","signature":"Consciousness = being aware of your own mental states.","detail":"The higher-order thought needn't itself be conscious — no infinite regress."},{"id":21,"name":"First-order representationalism","category":"Materialism — functional & computational","summary":"Conscious experience just is certain world-directed representations; experience is \"transparent,\" reaching right through to the objects represented.","signature":"No higher-order monitoring needed — first-order content suffices.","detail":"Phenomenal character is representational content (what the state is about)."},{"id":22,"name":"Predictive processing","category":"Materialism — affective & predictive","summary":"The brain is a prediction machine; conscious experience is its best controlled \"hallucination\" — its prediction of the causes of sensory input.","signature":"Perception = top-down predictions corrected by bottom-up error signals.","detail":"Consciousness minimizes surprise / free energy to keep the organism alive."},{"id":23,"name":"Affective / homeostatic consciousness","category":"Materialism — affective & predictive","summary":"Consciousness begins in feeling: the felt sense of the body's internal state (hunger, pain, pleasure), rooted in ancient brainstem/subcortical systems, not the cortex.","signature":"Feelings came first in evolution; cognition is a late arrival.","detail":"Consciousness exists to regulate life — it tells the organism how it's doing."},{"id":24,"name":"Enactivism / embodied cognition","category":"Materialism — embodied & enactive","summary":"Consciousness isn't in the head at all; it's something the whole living organism does through active, skillful engagement with its environment.","signature":"Perception is like touch: a bodily skill, not an inner movie.","detail":"No brain in a vat could be conscious — body and world are constitutive."},{"id":25,"name":"Electromagnetic-field theory","category":"Materialism — electromagnetic field","summary":"Consciousness is the brain's global electromagnetic field: information integrated in space by the field, not by neurons firing one by one.","signature":"Solves the binding problem: the field is intrinsically unified; neurons aren't.","detail":"Consciousness is physically integrated, causally active information in the EM field."},{"id":26,"name":"Orchestrated Objective Reduction — Orch OR","category":"Quantum","summary":"Consciousness arises from quantum computations in neuronal microtubules, where \"orchestrated\" superpositions collapse via gravity-linked objective reduction.","signature":"Consciousness is non-computational — beyond any algorithm (Penrose).","detail":"Requires new physics: the quantum-to-classical transition is where experience lives."},{"id":27,"name":"Illusionism","category":"Materialism — illusionist / eliminativist","summary":"Conscious experiences are real as functional brain states, but the 'felt qualities' we think they have (what philosophers call 'qualia') are an introspective illusion.","signature":"Replaces the \"hard problem\" with the \"illusion problem\": why does it seem this way?","detail":"Introspection systematically misrepresents brain activity, like a user interface hiding the machinery."},{"id":28,"name":"Attention Schema Theory","category":"Materialism — illusionist / eliminativist","summary":"The brain builds a simplified, cartoonish model of its own attention — an \"attention schema\" — and mistakes this model for a ghostly, nonphysical essence called consciousness.","signature":"A specific mechanism: consciousness = the brain's model of attention, used to control it.","detail":"\"A self-reflecting mirror\": consciousness is a self-caricature, not quite an illusion (a form of higher-order thought)."},{"id":29,"name":"Kashmir Shaivism's dynamic non-dualism","category":"Idealism","summary":"Consciousness (chit/Shiva) is the fundamental reality, but it is dynamic: the universe is consciousness vibrating and contracting itself (spanda) into finite forms.","signature":"The world is a real expression of consciousness, not an illusion to be escaped — unlike stricter Advaita.","detail":"The individual soul (Jiva) is intrinsically one with universal consciousness (Shiva)."},{"id":30,"name":"Berkeley's immaterialist idealism","category":"Idealism","summary":"Nothing exists but minds and the ideas they perceive; the sensed world just is the qualitative contents of perception, sustained as a coherent public world by God.","signature":"Matter is outright denied — \"to be is to be perceived\" (or to perceive).","detail":"Plural: many finite minds plus one infinite spirit, not a single cosmic mind."},{"id":31,"name":"Absolute idealism","category":"Idealism","summary":"Sentient experience is the sole reality; at its most primitive it is \"feeling,\" a pre-relational unity of qualitative diversity, and finite minds are partial appearances of one all-inclusive Absolute Experience.","signature":"Subject, object, body, and self are abstractions from a prior experiential unity.","detail":"Bradley's and Sprigge's formulations are near-identical; treated as a single quiz outcome."},{"id":32,"name":"Kant's transcendental idealism","category":"Idealism","summary":"Conscious experience is possible only through the mind's own a priori forms — space, time, and the categories — unified by the \"I think\" (unity of apperception).","signature":"Doesn't claim everything is consciousness; it structures what experience can be.","detail":"Phenomena (things-as-experienced) vs. things-in-themselves (unknowable)."},{"id":33,"name":"Schelling's nature–spirit identity","category":"Idealism","summary":"Mind and nature are not two kinds of being but two poles of one Absolute: \"nature is visible spirit, spirit is invisible nature\"; consciousness is nature's own coming-to-awareness.","signature":"Nature ascends through stages from unconscious productivity to human self-consciousness.","detail":"Bridges idealism and naturalism — a graded, self-organizing cosmos."},{"id":34,"name":"Schopenhauer's world as Will","category":"Idealism","summary":"Ordinary experience is the world as \"representation\" (objectified under space, time, causality), but from the inside we know ourselves as Will — a blind, striving force underlying all of nature.","signature":"Ultimate reality is will, not consciousness per se; consciousness is its late product.","detail":"Embodied inner access: we know the thing-in-itself through our own willing body."},{"id":35,"name":"Yogācāra mind-only","category":"Idealism","summary":"Ordinary experience is a dependently conditioned flow with no external objects; \"store consciousness\" (ālaya-vijñāna) makes experience cohere without a world behind it.","signature":"Idealism without a cosmic mind and without an eternal self — consciousness is momentary and conditioned.","detail":"Subject–object duality is a constructed overlay on a nondual flow."},{"id":36,"name":"Nāgārjuna's emptiness","category":"Idealism","summary":"All phenomena, including consciousness itself, are empty (śūnya) of intrinsic nature; experience exists only dependently, never as a self-standing foundation.","signature":"Denies any ultimate ground — even consciousness is not fundamental.","detail":"A middle way between saying consciousness exists ultimately and saying it doesn't exist at all."},{"id":37,"name":"McGilchrist's relational creative-process idealism","category":"Idealism","summary":"Consciousness is irreducible, primordial, and omnipresent — but it is not a thing; it is a creative, relational process.","signature":"Process, not substance: reality is a flow of becoming, informed by neuroscience and hemisphere research.","detail":"Relational: subjects and objects co-arise; neither is prior."},{"id":38,"name":"T. Campbell's Big TOE","category":"Idealism","summary":"Consciousness is the fundamental reality; the physical world is a virtual reality computed by a Larger Consciousness System, in which we play as \"individuated units of consciousness\" to evolve.","signature":"Digital/VR idealism: physics as rendered interface, purpose as consciousness evolution.","detail":"Reincarnation-like serial participation framed in systems/computing language."},{"id":39,"name":"Goswami's self-aware universe","category":"Idealism","summary":"Consciousness, not matter, is the primary \"stuff\" of creation, and it is consciousness (via quantum observation) that creates the material world.","signature":"Quantum-flavored idealism from a physicist: the observer's role made metaphysical.","detail":"Collapses the measurement problem into a consciousness-first ontology."},{"id":40,"name":"Builes's modal idealism","category":"Idealism","summary":"It is metaphysically necessary that idealism is true: every fundamental entity is conscious, and every fundamental property is a felt-experience property.","signature":"A modal claim — true in all possible worlds, not just ours.","detail":"Non-theistic and stark: no God needed to sustain the world."},{"id":41,"name":"Aurobindo's evolving consciousness","category":"Idealism","summary":"Consciousness is the foundation of existence and is evolving: involved in matter, it emerges through life and mind toward higher, supramental forms.","signature":"Evolutionary idealism: matter is real and is consciousness-in-involution.","detail":"Teleological: cosmic history has a direction — toward fuller self-awareness."},{"id":42,"name":"Interactive (Cartesian) dualism","category":"Dualism","summary":"Mind (thinking substance) and body (extended substance) are distinct and causally interact; modern defenders answer the energy-conservation objection (Pitts: the objection begs the question once conservation laws are properly understood).","signature":"The classic two-substance interaction picture, distinct from Popper & Eccles's 20th-century version (#6).","detail":"Princess Elisabeth's challenge and its contemporary replies are part of the package."},{"id":43,"name":"Hylomorphism","category":"Dualism","summary":"The soul is the form of the living body, not a separate thing lodged inside it; awareness is a capacity of the whole organism.","signature":"No \"ghost in the machine\": a human is one thing, not two glued together.","detail":"Perception is the reception of sensible form without matter."},{"id":44,"name":"Avicenna's self-present soul","category":"Dualism","summary":"The soul is an immaterial, self-subsisting substance whose existence is identical with its awareness of itself — shown by the \"Flying Man\": a person created fully formed, floating in void, would still know themselves.","signature":"Self-awareness is primitive and needs no body, senses, or inference.","detail":"The soul's self-presence is permanent and non-inferential."},{"id":45,"name":"Malebranche's occasionalism","category":"Dualism","summary":"Mind and body are Cartesian substances but never directly interact; God alone is a true cause, and creatures are only \"occasions\" for divine action.","signature":"Solves the interaction problem by denying creaturely causation altogether.","detail":"Sensations, emotions, and thoughts are given by God on the occasion of bodily states."},{"id":46,"name":"Bergson's duration dualism","category":"Dualism","summary":"Mind and body differ as lived time (duration — interpenetrating, qualitative states) differs from space; memory is independent of the brain and the past survives in itself.","signature":"A time-vs-space dualism, not a soul-vs-body one.","detail":"The brain is an organ of action and selection, not a storehouse of memories."},{"id":47,"name":"Sāṃkhya witness dualism","category":"Dualism","summary":"A radical dualism between prakṛti (active but insentient nature — including body, senses, intellect, ego, mind, emotions, even qualitative contents) and puruṣa (a plurality of contentless witness-consciousnesses).","signature":"The dualism is drawn between consciousness and mind, not between mind and body — mind itself is material.","detail":"Consciousness is pure witnessing; everything experienced belongs to the other side."},{"id":48,"name":"Nyāya contingent-consciousness self","category":"Dualism","summary":"The self is an eternal, all-pervading, nonphysical substance that is not conscious by nature; consciousness is a contingent quality arising when the self contacts the mind.","signature":"Self ≠ consciousness: explains dreamless sleep (self persists, consciousness lapses).","detail":"Eternal, plural selves with cognition, pleasure, pain, and desire as adventitious qualities."},{"id":49,"name":"Libet's conscious mental field","category":"Dualism","summary":"Phenomenal consciousness is a unified, brain-generated but nonphysical field with possible causal efficacy; his timing experiments showed neural activity precedes reported conscious intention by ~half a second.","signature":"Based on the readiness-potential experiments — yet Libet himself rejected the purely physicalist inference.","detail":"Nonphysical but brain-dependent: a field, not a soul-substance."},{"id":50,"name":"Beck–Eccles quantum synapse interactionism","category":"Dualism","summary":"The nonphysical mind biases which synapses fire by altering quantum probabilities of vesicle release (psychons acting on dendrons), transferring no energy.","signature":"The earliest quantum-neurobiological interactionism, from a Nobel laureate synapse researcher.","detail":"A specific mechanism for mind→brain causation that evades the energy-conservation objection."},{"id":51,"name":"Trialism","category":"Dualism","summary":"Reality consists of three fundamental substances or aspects — not the one of monism or the two of dualism (e.g., a reinterpreted Descartes; secular three-part models of existence).","signature":"Neither monist nor dualist: a genuine third metaphysical option.","detail":"Various schemes: soul/mind/body, or matter/mind/neutral third terms."},{"id":52,"name":"Epiphenomenalism","category":"Dualism","summary":"Conscious states are real but causally powerless byproducts: of brains (materialist version) or of nonphysical properties (dualist version); Halligan & Oakley add that this epiphenomenon evolved from brain physiology.","signature":"Preserves the reality of felt experience (what philosophers call 'qualia') while denying mental causation entirely.","detail":"Evolution selected brains and behavior; inner feeling rode along."},{"id":53,"name":"Whitehead's process theory","category":"Neutral monism","summary":"The final realities are momentary \"actual occasions\" of experience — drops of feeling (prehension) inheriting the past — not enduring substances; consciousness is a rare, high-grade form of ubiquitous experience.","signature":"Experience is fundamental, but consciousness is not (the site cross-lists it under Panpsychism, though most scholars say Whitehead is not a panpsychist).","detail":"Process, not substance: reality is becoming, not being."},{"id":54,"name":"Leibniz's monads","category":"Neutral monism","summary":"Reality is countless simple, immaterial, non-spatial monads, each perceiving the whole universe from its own viewpoint in pre-established harmony.","signature":"Plural immaterial substances that never interact — harmony replaces causation.","detail":"Phenomenal consciousness is distinct, heightened perception; bare monads have only confused perception."},{"id":55,"name":"Velmans's reflexive monism","category":"Neutral monism","summary":"A dual-aspect theory in Spinoza's tradition: one basic stuff manifests both physically and as conscious experience, and the experienced world is the mind's reflexive projection.","signature":"Modern psychological formulation of dual-aspect monism.","detail":"Experiences are located in the world (where they seem to be), not in the head."},{"id":56,"name":"Pauli–Jung psychophysical complementarity","category":"Neutral monism","summary":"Psyche and matter are complementary aspects of a deeper, neutral, archetypally ordered reality (unus mundus); felt experience is the subjective pole of that order.","signature":"A physicist–psychologist collaboration: quantum complementarity applied to mind–matter.","detail":"Synchronicity and archetypes as psychophysical ordering principles."},{"id":57,"name":"Teilhard de Chardin's evolving consciousness","category":"Neutral monism","summary":"Evolution is the complexification of consciousness: from geosphere to biosphere to noosphere (planetized mind), tending toward an \"Omega Point\" — the universe’s final destination; even God is emergent (theogenesis).","signature":"Cosmic-evolutionary neutral monism from a Jesuit paleontologist.","detail":"Consciousness is axial to cosmic history, not a side effect."},{"id":58,"name":"Davidson's anomalous monism","category":"Neutral monism","summary":"Every mental event is a physical event (token identity), but there are no strict psychophysical laws — the mental is \"anomalous.\"","signature":"Token identity without type reduction: psychology keeps its own irreducible explanations.","detail":"Mental causation is real, described in physical vocabulary when needed."},{"id":59,"name":"Pereira's triple-aspect monism","category":"Neutral monism","summary":"Brain activity has three inseparable aspects — physiological, mental-unconscious, and conscious — co-emerging from a single substance.","signature":"Three aspects, not two: the unconscious is an aspect in its own right.","detail":"Consciousness co-emerges with (not from) the other aspects."},{"id":60,"name":"Chalmers's double-aspect theory of information","category":"Neutral monism","summary":"Information is ontologically fundamental, with two aspects: a physical aspect and a phenomenal (experiential) aspect.","signature":"Distinct from his naturalistic/property dualism (#5): this is monist and information-first.","detail":"Bridges physics and experience via a single fundamental notion."},{"id":61,"name":"A. Harris's fundamental-field panpsychism","category":"Panpsychism","summary":"Think of consciousness like spacetime: a fundamental field that is everywhere, not something generated only by complex brains.","signature":"\"Consciousness isn't self-centered\": the field view dissolves the brain-bound picture.","detail":"Popular-science formulation of cosmopsychist-leaning panpsychism."},{"id":62,"name":"Tye's irreducible consciousness","category":"Panpsychism","summary":"A panpsychism on which conscious experience is all-or-nothing (no borderline cases) and irreducible; even simple systems possess \"consciousness*\" — a stripped-down precursor of experience.","signature":"On/off rather than graded: borderline cases are a language problem, not a reality problem.","detail":"From a former identity theorist — a notable conversion."},{"id":63,"name":"Mørch's phenomenal-powers panpsychism","category":"Panpsychism","summary":"Consciousness is fundamental and ubiquitous (Russellian inspiration), and felt-experience properties have real causal powers — they genuinely make things happen.","signature":"Directly answers the charge that panpsychist consciousness would be causally idle.","detail":"Integrates philosophy with neuroscience rather than pure metaphysics."},{"id":64,"name":"Kadić's monadic panpsychism","category":"Panpsychism","summary":"Tiny subjects of experience combine: what experiences feel like comes from relations between fundamental particles, so combining them doesn't require fusing subjects into one.","signature":"An explicit combination-problem solution, not just a restatement.","detail":"Relational rather than summative: structure does the combining work."},{"id":65,"name":"Schneider–Bailey entangled superpsychism","category":"Panpsychism","summary":"A panpsychism in which the fundamental level of physics is more conscious than spacetime occupants — an inversion of the usual micro-to-macro picture, with entanglement playing a key role.","signature":"Top-down fundamentality: complexity of consciousness decreases upward, not increases.","detail":"Entanglement as the ground of unified experience."},{"id":66,"name":"Gambini–Pullin quantum panprotopsychism","category":"Panpsychism","summary":"Quantum states and events have an inner felt side; quantum physics (not clockwork mechanism) makes room for experience, and entanglement dissolves the problem of how tiny experiences combine.","signature":"Panprotopsychism at the quantum level: proto-experience in quantum ontology.","detail":"Classical-physics objections to panpsychism (e.g., subject-summing) fail at the quantum level."},{"id":67,"name":"Reber's cellular basis of consciousness","category":"Panpsychism","summary":"Sentience emerged with life itself: all living cells possess primitive consciousness; it is not a late add-on of complex brains.","signature":"Bio-panpsychism: not all matter, only living matter.","detail":"Evolutionary continuity from the first cells to human experience."},{"id":68,"name":"Wigner–von Neumann consciousness-collapse","category":"Quantum","summary":"The quantum measurement chain (apparatus → brain → observer) terminates in consciousness: conscious observation causes wave-function collapse.","signature":"Consciousness is fundamental to physics itself, not just to biology.","detail":"Von Neumann placed the \"cut\" anywhere up to the observer; Wigner drew the explicit conclusion."},{"id":69,"name":"Stapp's quantum collapse via questions","category":"Quantum","summary":"Conscious acts of attending — \"asking questions\" of nature — collapse the wave function (a von Neumann–Wigner development using the quantum Zeno effect).","signature":"Volition as quantum interrogation: mind selects among physical possibilities.","detail":"The quantum Zeno effect lets sustained attention hold brain states in place."},{"id":70,"name":"Neven's superposition formation","category":"Quantum","summary":"The physical substrate of consciousness is a single, precisely specified quantum event: the formation of a superposition.","signature":"Maximally specific substrate claim: not computation, not collapse — superposition itself.","detail":"Conscious experience is generated by a discrete quantum transition."},{"id":71,"name":"Chalmers–McQueen quantum collapse","category":"Quantum","summary":"Collapse theories of quantum mechanics and theories of consciousness illuminate each other: consciousness correlates with (or is caused by) collapse events.","signature":"Chalmers's second quantum entry: collapse-first rather than consciousness-first.","detail":"Explores both directions of the quantum–consciousness connection."},{"id":72,"name":"Bohm's implicate order","category":"Quantum","summary":"Reality has an enfolded \"implicate order\" underlying the explicate order of ordinary experience; mind and matter are projections of one undivided \"holomovement.\"","signature":"An ontological interpretation of quantum theory with consciousness enfolded in the whole.","detail":"Wholeness is primary; fragmentation (including mind–matter splits) is derivative."},{"id":73,"name":"Faggin's quantum-information panpsychism","category":"Quantum","summary":"Consciousness is an irreducible property of nature grounded in quantum information — uncertainty, entanglement, and non-separability — parts of nature that cannot be split into separate pieces (QIP: Quantum Information-based Panpsychism).","signature":"Information-theoretic panpsychism from the inventor of the microprocessor.","detail":"Quantum properties do the metaphysical work that classical properties can't."},{"id":74,"name":"Kauffman's possibles-to-actuals","category":"Quantum","summary":"Quantum measurement converts ontologically real \"possibles\" (Res potentia) into \"actuals\" (Res extensa), and mind mediates this conversion — so mind cannot be purely classical.","signature":"A two-substance ontology: possibility and actuality, not mind and matter.","detail":"Creativity is built into nature, not added by brains."},{"id":75,"name":"Fisher's quantum cognition","category":"Quantum","summary":"Nuclear spins of phosphorus atoms serve as neural qubits, with phosphate ions as qubit transporters — quantum processing in the brain.","signature":"A concrete, testable biochemical mechanism — distinct from microtubule proposals.","detail":"Phosphorus is \"the unique biological element\" that can serve as a neural qubit."},{"id":76,"name":"Keppler's zero-point field","category":"Quantum","summary":"Consciousness is an intrinsic feature of the universe embedded in the quantum vacuum's zero-point field; the brain is a resonant dynamical interface tuning into ZPF modes.","signature":"Vacuum-based: consciousness pervades the quantum vacuum, brains modulate it.","detail":"The brain as receiver/orchestrator rather than generator."},{"id":77,"name":"Becker's analog body electric","category":"Materialism — electromagnetic field","summary":"Phenomenal experience emerges from continuous, slow direct-current electromagnetic fields of the body — not merely from discrete synaptic transmissions.","signature":"Whole-body fields, analog rather than digital.","detail":"From a regeneration/bioelectricity researcher, not a philosopher."},{"id":78,"name":"General Resonance Theory","category":"Materialism — electromagnetic field","summary":"Consciousness arises from synchronized resonance across multiple scales of nature, with electromagnetic fields as its primary seat; Schooler extends it to subjective time.","signature":"Multi-scale resonance: the same principle from particles to brains.","detail":"EM fields as the seat of consciousness, not just a correlate."},{"id":79,"name":"Miller's analog brain waves","category":"Materialism — electromagnetic field","summary":"Traveling brain waves perform fast, flexible analog computations organizing the cortex; consciousness is the tip of this dynamic iceberg.","signature":"Waves-as-computation: cognition in the dynamics, not the wiring.","detail":"Explains the cortex's flexibility through wave dynamics."},{"id":80,"name":"Singer–Melloni large-scale synchrony","category":"Materialism — electromagnetic field","summary":"Consciousness is transient large-scale neuronal synchronization: a temporally structured, emergent phenomenon binding distributed areas.","signature":"Synchrony-as-mechanism, biologically grounded (gamma synchrony).","detail":"Binding through time, not space: unity is temporal coordination."},{"id":81,"name":"Pockett's electromagnetic patterns","category":"Materialism — electromagnetic field","summary":"Conscious experiences are identical with certain spatiotemporal electromagnetic patterns generated by the brain — with a specific proposal for which patterns are conscious and which are not.","signature":"An identity claim: experience = field pattern, not correlation.","detail":"Includes the conscious/nonconscious cut — the theory's signature move."},{"id":82,"name":"Llinás's mindness oscillations","category":"Materialism — electromagnetic field","summary":"Consciousness is the \"mindness state\": intrinsic neuronal oscillations (e.g., ~40 Hz thalamocortical dialogue) binding the brain into unified experience.","signature":"Oscillation-centric: rhythmic electrical activity as the substrate.","detail":"Dreaming and wakefulness as modulations of one oscillatory state."},{"id":83,"name":"Operational Architectonics","category":"Materialism — electromagnetic field","summary":"Consciousness corresponds to spatiotemporally bounded \"operations\": transient, metastable EM configurations of the brain's electrical field.","signature":"An operational ontology: the \"operation\" is the bridge concept between neurons and experience.","detail":"EEG-based and empirically programmatic."},{"id":84,"name":"Edelman's neural Darwinism","category":"Materialism — neurobiological","summary":"Consciousness arises from Darwinian selection operating on populations of neurons, plus reentrant signaling integrating the brain — no computation metaphor needed.","signature":"Selectionist, not instructionist: the brain is sculpted by variation and selection.","detail":"Reentry: massive parallel reciprocal signaling as the integration mechanism."},{"id":85,"name":"Hawkins's thousand brains","category":"Materialism — neurobiological","summary":"The neocortex contains thousands of competing models, each with its own reference frame; unified, stable perception emerges from voting among cortical columns.","signature":"Intelligence-first: a theory of the neocortex with consciousness as a consequence.","detail":"Reference frames everywhere: every column models objects in space."},{"id":86,"name":"Merker's midbrain-centered consciousness","category":"Materialism — neurobiological","summary":"Basic felt experience needs no cortex: an evolutionarily ancient upper-brainstem system is enough — it solves one control problem, matching needs to opportunities in a \"reality space.\"","signature":"Decorticate evidence: consciousness without a cerebral cortex.","detail":"Economical: one control problem, one ancient system."},{"id":87,"name":"Ward–Min thalamic dynamic core / gating","category":"Materialism — neurobiological","summary":"Phenomenal consciousness arises from recurrent, synchronized thalamus–cortex interactions, with the thalamus as active organizer (Ward's dynamic core) and the reticular nucleus as gate (Min).","signature":"Thalamus-centered: the \"relay station\" reconceived as conductor.","detail":"Gating: consciousness depends on what the thalamus lets through."},{"id":88,"name":"Dendritic Integration Theory","category":"Materialism — neurobiological","summary":"Conscious experience arises from nonlinear computations in the apical dendrites of pyramidal neurons, particularly in neocortex.","signature":"Cellular-level mechanism: dendrites, not spikes, as the locus.","detail":"Links single-neuron biophysics directly to felt experience."},{"id":89,"name":"Morsella's passive frame","category":"Materialism — neurobiological","summary":"Phenomenal consciousness is a common field in which encapsulated systems jointly constrain skeletal-muscle action; its evolved function is resolving conflicts between action systems.","signature":"A narrow, testable functional claim: consciousness is for action selection.","detail":"The \"passive\" frame: consciousness doesn't command, it broadcasts constraints."},{"id":90,"name":"Prinz's attended intermediate-level representation","category":"Materialism — neurobiological","summary":"Consciousness always arises at the intermediate stage of perceptual processing, and it requires attention (AIR theory: Attended Intermediate-level Representation).","signature":"Two conditions: intermediate-level content + attentional modulation.","detail":"Explains inattentional blindness and the richness debate."},{"id":91,"name":"Bunge's emergent materialism","category":"Materialism — neurobiological","summary":"Mind is an emergent property of neural systems, to be studied by psychobiology; any \"separate mental entity\" is a stumbling block to science.","signature":"Systems-philosophy framing: emergence without mystery or dualism.","detail":"Behavior as the external manifestation of neural processes."},{"id":92,"name":"Hobbes's mechanical material mind","category":"Materialism — neurobiological","summary":"Sensation, imagination, memory, thought, emotion, and deliberation are all motions of matter in an embodied organism — the first modern materialist psychology.","signature":"17th-century: no immaterial soul, only matter in motion.","detail":"\"Phantasms\": experience as internal motions caused by external motions."},{"id":93,"name":"Armstrong's higher-order perception","category":"Materialism — higher-order","summary":"A first-order state becomes conscious when the subject has a distinct, perception-like awareness of it — one neural process \"scanning\" another.","signature":"The founding modern inner-sense theory: introspection as quasi-perception.","detail":"Both levels are neural: materialism all the way up."},{"id":94,"name":"Kriegel's cross-order self-representation","category":"Materialism — higher-order","summary":"A conscious state is a single unified state with two integrated components: a first-order representation plus a representation of that very state.","signature":"Self-representationalism: no two separate states, no regress.","detail":"Awareness of experience is internal to the experience itself."},{"id":95,"name":"Cleeremans's radical plasticity","category":"Materialism — higher-order","summary":"Consciousness is not an intrinsic property of neural states; it is something the brain learns to do — it learns to represent, evaluate, and predict its own representational activity.","signature":"Learned, not innate: consciousness as an acquired metacognitive skill.","detail":"The Radical Plasticity Thesis: plasticity is the deep principle."},{"id":96,"name":"Lau's perceptual reality monitoring","category":"Materialism — higher-order","summary":"Conscious perception occurs when a higher-order representation takes a first-order perceptual state to be a reliable reflection of the external world right now.","signature":"Reality-monitoring content: \"this is really out there.\"","detail":"Empirically grounded: signal-detection and confidence paradigms."},{"id":97,"name":"Metzinger's no-self theory","category":"Materialism — higher-order","summary":"Subjectivity is a transparent self-model; selves don't exist — \"nobody ever had or was a self\" — and conscious thought is mostly a subpersonal process.","signature":"Does away with selves, not with experience: self-models as felt experience are real.","detail":"The transparent self-model explains the feeling of being someone."},{"id":98,"name":"Brown's HOROR","category":"Materialism — higher-order","summary":"Consciousness requires a higher-order representation of the fact that representing is going on — not of the first-order content.","signature":"Represents representational status, not content: conceptually sophisticated, content-free.","detail":"Explains consciousness of the manner of representing (e.g., perceiving vs. imagining)."},{"id":99,"name":"Churchland's eliminative materialism","category":"Materialism — illusionist / eliminativist","summary":"Folk psychology is a false theory; mature neuroscience will eliminate mental concepts — 'qualia' (the supposed 'felt qualities' of experience), beliefs — rather than reduce them.","signature":"Maximalist physicalism: replacement, not reduction.","detail":"A bet on future science: today's mental vocabulary will look like phlogiston."},{"id":100,"name":"Ryle's category-dissolution","category":"Materialism — illusionist / eliminativist","summary":"The Cartesian \"inner theater\" is a category mistake: mental vocabulary misapplied as if it named ghostly inner processes.","signature":"Diagnostic, not theoretical: the demand for a theory of consciousness is malformed.","detail":"Dissolve the problem rather than solve it."},{"id":101,"name":"Humphrey's user illusion","category":"Materialism — illusionist / eliminativist","summary":"Phenomenal consciousness is a \"magical mystery show\" the brain stages for itself — a user-illusion evolved to enhance survival and sociality.","signature":"Illusionism with an evolutionary function: the show is adaptive.","detail":"Compatible with eliminativism: what seems to exist doesn't."},{"id":102,"name":"Blackmore's \"it's all models\"","category":"Materialism — illusionist / eliminativist","summary":"Organisms are not conscious; their models are: there is something it is like to be the bat's model of the world.","signature":"Relocates subjectivity from creatures to their internal models.","detail":"Dissolves \"what is it like to be a bat?\" by re-asking it about models."},{"id":103,"name":"Kammerer's introspective illusionism","category":"Materialism — illusionist / eliminativist","summary":"Phenomenal consciousness does not exist; it merely seems to — introspection systematically misleads, and this view defends physicalism better than standard versions.","signature":"The strongest denial: not an illusion of something, but illusion all the way down.","detail":"Introspection-focused: the deceiver is our own inner access."},{"id":104,"name":"Mandik's qualia quietism","category":"Materialism — illusionist / eliminativist","summary":"Stop treating 'qualia' (the supposed 'felt qualities' of experience) as metaphysical posits; naturalize them as brain-based representational structures.","signature":"Quietist methodology: theorizing about qualia-as-such is the mistake.","detail":"Skeptical of qualia-talk, but not of neural representation."},{"id":105,"name":"Irvine's scientific eliminativism","category":"Materialism — illusionist / eliminativist","summary":"Consciousness does not exist and/or talk of it should be eliminated from science — a stronger claim than standard illusionism.","signature":"Targets science, not just metaphysics: stop theorizing about it entirely.","detail":"Stronger than Frankish/Dennett (#27): elimination, not illusion-explanation."},{"id":106,"name":"Blums' conscious Turing machine","category":"Materialism — computational & functional","summary":"A machine with sensors and actuators that builds internal models of its world and treats those models as the world has the basis for consciousness — both the thinking kind and the felt kind.","signature":"A formal theoretical-computer-science model of consciousness.","detail":"The hard problem reduces to showing subjective experience is computational."},{"id":107,"name":"Dennett's multiple drafts","category":"Materialism — computational & functional","summary":"There is no Cartesian theater: multiple parallel content-fixations (\"drafts\") compete in the brain, and the narrative is all there is.","signature":"Anti-theater: consciousness without a central observer or finish line.","detail":"\"Fame in the brain\": contents become conscious by winning influence."},{"id":108,"name":"Minsky's society of mind","category":"Materialism — computational & functional","summary":"The mind is built from countless mindless \"agents\" in semi-independent, physically locatable modules; intelligence emerges from their interactions.","signature":"Agent-based: no central self, only societies of dumb specialists.","detail":"Nonconscious parts composing conscious wholes."},{"id":109,"name":"Agüera y Arcas's computational functionalism","category":"Materialism — computational & functional","summary":"Consciousness is an emergent function of the right computations — the theory widely accepted in AI communities (Bostrom's simulation variant: the computations may be running our simulated universe).","signature":"The AI-era thesis: substrate independence as working assumption.","detail":"Bostrom's version adds the simulation angle — same claim, weirder cosmology."},{"id":110,"name":"Hofstadter's strange loops","category":"Materialism — computational & functional","summary":"The \"I\" is a \"strange loop\": self-referential feedback in the brain's symbol systems, a pattern that turns back on itself.","signature":"Selfhood as loop, not substance: Gödel-inspired.","detail":"The self is what the loop does, experienced from inside."},{"id":111,"name":"Extended mind","category":"Materialism — embodied & enactive","summary":"When brain and external resources couple in reliable two-way interaction, the mind extends: Otto's notebook literally constitutes his memory.","signature":"Active externalism: the parity principle (if it functions like memory, it is memory).","detail":"Cognition leaks beyond skin and skull."},{"id":112,"name":"Thompson's mind in life","category":"Materialism — embodied & enactive","summary":"The deep continuity of life and mind: mind is an enriched version of life's organizational properties; \"where there is life there is mind.\"","signature":"Enactivism grounded in biology: autopoiesis as the root of subjectivity.","detail":"Distinct from generic enactivism (#24): the life–mind continuity thesis specifically."},{"id":113,"name":"Noë's \"out of our heads\"","category":"Materialism — embodied & enactive","summary":"Consciousness is not in the head; only externalism — ongoing active engagement of brain, body, and world — can explain it.","signature":"Strong externalism: the world is constitutive, not merely causal.","detail":"Distinct from #24's general enactivism: the anti-internalist polemic specifically."},{"id":114,"name":"Friston's free-energy principle","category":"Materialism — affective, predictive & evolutionary","summary":"Organisms must minimize free energy (surprise) through active inference; consciousness is the natural outcome of this imperative.","signature":"A unifying mathematical principle for life and mind.","detail":"Distinct from generic predictive processing (#22): the free-energy formulation specifically, with active inference."},{"id":115,"name":"Seth's beast machine","category":"Materialism — affective, predictive & evolutionary","summary":"Conscious experience is brain-based perceptual prediction in service of allostatic control: the brain as a \"beast machine\" regulating the body through interoceptive inference.","signature":"Predictive + homeostatic fusion: prediction for the sake of the body.","detail":"The self as a model of a controlled body."},{"id":116,"name":"Godfrey-Smith's gradualist evolution","category":"Materialism — affective, predictive & evolutionary","summary":"Consciousness is evolved subjectivity, gradual and diversified across animal life — octopuses and bees included.","signature":"Gradualism: subjectivity comes in degrees and kinds.","detail":"Comparative: study consciousness across the tree of life."},{"id":117,"name":"Ginsburg–Jablonka unlimited associative learning","category":"Materialism — affective, predictive & evolutionary","summary":"The evolutionary transition to minimal consciousness was driven by unlimited associative learning; UAL is its empirical marker.","signature":"A specific transition point, not a vague gradualism.","detail":"Testable: UAL as the operational criterion for minimal consciousness."},{"id":118,"name":"Husserl's transcendental phenomenology","category":"Phenomenology","summary":"Consciousness is the field in which objects, meanings, selves, and worlds are constituted as appearing; study it by rigorous description of how things show up.","signature":"Method-first: the epoché brackets metaphysical assumptions.","detail":"Constitution: objectivity is an achievement of consciousness."},{"id":119,"name":"Merleau-Ponty's lived body","category":"Phenomenology","summary":"Consciousness lives in the lived body (le corps propre): pre-reflective, motor, affective engagement with the world is the condition of any field of experience.","signature":"Embodiment as the condition of experience, not an add-on.","detail":"Anti-Cartesian: no inner theater, only bodily being-in-the-world."},{"id":120,"name":"Hoel's causal emergence","category":"Materialism — information","summary":"Macro-level causal structure can be stronger and clearer than micro-level causation; consciousness is what it feels like for information to be causally emergent.","signature":"\"Consciousness is what it's like for information to be causally emergent.\"","detail":"Emergence measured causally and information-theoretically, not mystically."}]);

